using System.Text.Json;using Microsoft.EntityFrameworkCore;using TrekStride.Api.Infrastructure;namespace TrekStride.Api.Application;public interface ITrailService{Task<object[]>Trails();Task<object[]>Leaderboard();}public class TrailService:ITrailService{readonly AppDbContext db;public TrailService(AppDbContext d)=>db=d;public async Task<object[]>Trails(){var x=await db.Trails.AsNoTracking().ToListAsync();return x.Count==0?Demo():x.Select(t=>(object)new{t.Id,t.Name,t.Location,t.DistanceKm,t.ElevationM,t.Difficulty,t.Rating,t.Walkers,coordinates=JsonSerializer.Deserialize<object>(t.CoordinatesJson)}).ToArray();}public async Task<object[]>Leaderboard(){var x=await db.Walks.GroupBy(w=>w.Nickname).Select(g=>new{nickname=g.Key,km=g.Sum(w=>w.DistanceKm)}).OrderByDescending(x=>x.km).Take(50).ToArrayAsync();return x.Cast<object>().ToArray();}static object[]Demo()=>new object[]{new{Id=1,Name="Belgrad Ormanı Kuzey Loop",Location="İstanbul",DistanceKm=8.7,ElevationM=214,Difficulty="Orta",Rating=4.9,Walkers=1503,coordinates=new[]{new{latitude=41.18,longitude=28.992},new{latitude=41.19,longitude=29.005}}}};}
